import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CQdiwDJy.js";const p=JSON.parse('{"title":"终端界面（TUI）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tui.md","filePath":"guide/tui.md","lastUpdated":1788601681000}'),s={name:"guide/tui.md"};function d(r,e,n,l,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="终端界面-tui" tabindex="-1">终端界面（TUI） <a class="header-anchor" href="#终端界面-tui" aria-label="Permalink to &quot;终端界面（TUI）&quot;">​</a></h1><p><code>tau tui</code> 是全键盘的终端交互界面：同一个引擎、同一道审查门，只是把计划、审查与执行搬进了全屏 TUI。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tui</span></span></code></pre></div><h2 id="设计要点" tabindex="-1">设计要点 <a class="header-anchor" href="#设计要点" aria-label="Permalink to &quot;设计要点&quot;">​</a></h2><ul><li><strong>键盘优先</strong>：所有操作可在不碰鼠标的情况下完成，方向键/回车浏览与选择，快捷键参考界面内帮助。</li><li><strong>斜杠命令面板</strong>：在空行输入 <code>/</code> 立即弹出可过滤的命令面板——继续输入缩小范围，<code>↑</code>/<code>↓</code> 移动，<code>Tab</code>/<code>Enter</code> 插入命令，<code>Esc</code> 关闭；面板、分发与 <code>/help</code> 共用同一份命令目录，展示与实际可执行永远一致。</li><li><strong>模型与思考选择（v0.6.2）</strong>：<code>/model</code> 从 provider 的实时/缓存目录中选模型（TTY 下交互选择器，非交互如实降级为列表），<code>/thinking</code> 展示或设置思考模式与强度——两者都只渲染当前 provider 真正支持的旋钮，与 CLI、WebUI 共享同一目录与配置层。</li><li><strong>ANSI 渲染</strong>：计划说明与结果以 ANSI 文本渲染（基于与 WebUI 共享的 markdown 抽象层——<code>@tau/markdown</code> 同时输出 HTML 与 ANSI 两种形态）。</li><li><strong>同样的门</strong>：TUI 里看到的审查结论与确认请求，和 CLI / WebUI 完全一致；它不是&quot;另一个更宽松的模式&quot;。</li></ul><h2 id="什么时候用-tui" tabindex="-1">什么时候用 TUI <a class="header-anchor" href="#什么时候用-tui" aria-label="Permalink to &quot;什么时候用 TUI&quot;">​</a></h2><ul><li>想在终端里连续多轮对话而不想反复敲 <code>tau ask</code>；</li><li>通过 SSH 在远程机器上工作，没有浏览器；</li><li>喜欢全屏界面的专注感，但不想离开终端。</li></ul><p>三兄弟的分工：<strong>CLI</strong> 一次性与管道，<strong>TUI</strong> 终端里的沉浸交互，<strong>WebUI</strong> 最丰富的可视化（思考面板、工具卡片、文件查看器）。引擎只有一个。</p>',8)])])}const g=t(s,[["render",d]]);export{p as __pageData,g as default};
